input.sparql:
SELECT ?zone ?label WHERE {
  ?zone a brick:Zone .
  OPTIONAL { ?zone rdfs:label ?label }
}

SELECT ?s ?label WHERE {
  ?s a brick:ElectricPowerSensor .
  OPTIONAL { ?s rdfs:label ?label }
}

SELECT ?s ?label ?tsid ?pointclass WHERE {
  ?s brick:hasLocation ?z .
  FILTER (?z = <http://buildgraph.org/BG_large_office_2004_0000#Zone_F1_Z01>) .
  OPTIONAL { ?s rdfs:label ?label }
  OPTIONAL {
    ?s ref:hasExternalReference ?ref .
    ?ref ref:hasTimeseriesId ?tsid .
  }
  OPTIONAL { ?s a ?pointclass }
}

SELECT ?point ?cls ?label ?ref ?tsid WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#Zone_F1_Z01> brick:hasPoint ?point .
  OPTIONAL { ?point a ?cls }
  OPTIONAL { ?point rdfs:label ?label }
  OPTIONAL { ?point ref:hasExternalReference ?ref }
  OPTIONAL {
    ?ref ?p ?tsid .
  }
}
